// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        // Ensure putAmount is non-zero and collectAmount is within balance constraints
        vm.assume(putAmount > 0 && putAmount <= type(uint256).max - 1e18);
        vm.assume(collectAmount <= putAmount);
        // Initialize contract by calling Initialized() to lock MinSum
        c.Initialized();
        // Record MinSum after initialization (should be 0 because SetMinSum was never called)
        uint256 initialMinSum = c.MinSum();
        // Deal ETH to this contract and call Put
        vm.deal(address(this), putAmount);
        c.Put{value: putAmount}(lockTime);
        // Warp time past unlockTime
        vm.warp(block.timestamp + lockTime + 1);
        // Call Collect(collectAmount)
        c.Collect(collectAmount);
        // Assert that MinSum was not changed
        assertTrue(c.MinSum() == initialMinSum);
    }
}

