pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _val, uint256 _collectAmount) public {
        // Ensure _collectAmount is reasonable to avoid reverts due to insufficient balance
        vm.assume(_collectAmount < 1 ether);
        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();
        // Fund the test caller and call Put to set balance and lock time
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(_lockTime);
        // Set MinSum to a specific value via SetMinSum after initialization (will revert and set to 0)
        vm.prank(address(0xdead));
        c.SetMinSum(_val);
        // Now call Collect
        c.Collect(_collectAmount);
        // Assert that MinSum equals the value set before the revert (0) because the true SetMinSum reverts
        // For the reference C, MinSum remains 0 because the only successful SetMinSum was during setup with value 0.
        assertTrue(c.MinSum() == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSumInit, uint256 minSumAfter, uint256 collectAmount) public {
        vm.assume(minSumInit <= type(uint256).max / 2);
        vm.assume(minSumAfter <= type(uint256).max / 2);
        vm.assume(collectAmount <= minSumInit);
        vm.assume(collectAmount <= minSumAfter);
        // Initialize the contract
        c.SetMinSum(minSumInit);
        c.Initialized();
        // Record MinSum before any Collect
        uint256 minSumBefore = c.MinSum();
        // Perform Collect
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        if (!success) {
            // If Collect reverts, MinSum should be unchanged
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed on revert");
        } else {
            // If Collect succeeds, MinSum must not have decreased below minSumBefore
            assertTrue(c.MinSum() >= minSumBefore, "MinSum decreased on successful Collect");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am, uint256 _deposit) public {
        // Bound inputs to realistic ranges
        _val = bound(_val, 1, 1e18);
        _lockTime = bound(_lockTime, 0, 365 days);
        _am = bound(_am, 0, 1e18);
        _deposit = bound(_deposit, _am, _am + 1e18);

        // Setup: initialize and set MinSum
        c.SetMinSum(_val);
        c.Initialized();

        // Deposit funds to msg.sender
        vm.deal(address(this), _deposit);
        c.Put{value: _deposit}(_lockTime);

        // Try to call Collect, record if it reverts
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // Rule: If Collect doesn't revert, MinSum must equal _val (the last successful SetMinSum value)
        // The bug makes MinSum=0 when revert occurs inside SetMinSum, but here SetMinSum succeeded, so bug only matters if Collect triggers it indirectly.
        // Actually the bug affects SetMinSum directly: when called after initialized, it sets MinSum=0 then reverts, but MinSum remains 0.
        // So a sequence: SetMinSum(_val), Initialized, then call SetMinSum again (which reverts but sets MinSum=0) then Collect would show difference.
        // We need a sequence that triggers this: call SetMinSum after Initialized.
        // But our rule: After any call to Collect, MinSum must equal the last value that SetMinSum was called with before Initialized (since after Initialized SetMinSum always fails, but bug sets MinSum=0).
        // Simpler: call SetMinSum after Initialized (will revert in reference but change MinSum in mutant), then call Collect, then check MinSum.
        // Redo: 
        vm.startPrank(address(0x1234));
        c.SetMinSum(999); // this call fails in reference but in mutant sets MinSum=0 before reverting
        vm.stopPrank();

        // Now call Collect
        (success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0));

        // Assert: MinSum must be either _val (if Collect didn't trigger SetMinSum internally) OR something else.
        // Actually the rule: MinSum should never be 0 after Initialized because SetMinSum cannot succeed after Initialized, so its value should stay at _val.
        // The bug makes MinSum=0 when SetMinSum is called after Initialized.
        // So after calling SetMinSum after Initialized, MinSum should still be _val in reference, but becomes 0 in mutant.
        // Then Collect doesn't change MinSum, so we can check after Collect.
        assertTrue(c.MinSum() == _val || success == false);
    }
}

