pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _lockTime1, uint256 _lockTime2, uint256 _am, uint256 _value1, uint256 _value2) public {
        // Bind input values to avoid overflow and excessive gas
        _minSum = bound(_minSum, 0, 1e30);
        _lockTime1 = bound(_lockTime1, 0, 365 days);
        _lockTime2 = bound(_lockTime2, 0, 365 days);
        _am = bound(_am, 0, 1e30);
        _value1 = bound(_value1, 0, 1e30);
        _value2 = bound(_value2, 0, 1e30);

        // Initialize contract and set MinSum
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0)); // dummy log contract
        c.Initialized();

        // Fund this contract so it can send value
        vm.deal(address(this), _value1 + _value2);

        // First user puts value
        address user = address(0x100);
        vm.deal(user, _value1);
        vm.prank(user);
        c.Put{value: _value1}(_lockTime1);

        // Second user (this contract) puts value and tries Collect
        vm.prank(address(this));
        c.Put{value: _value2}(_lockTime2);

        // Save MinSum before Collect
        uint minSumBefore = c.MinSum();

        // Call Collect
        c.Collect(_am);

        // Assert MinSum unchanged
        assertTrue(c.MinSum() == minSumBefore, "MinSum changed after Collect");
    }
}

