pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint _lockTime, uint _val, uint _collectAm, uint _minSum) public {
        // Bound inputs to avoid overflow and ensure meaningful tests
        _lockTime = bound(_lockTime, 0, 1000000);
        _val = bound(_val, 1, 1 ether);
        _collectAm = bound(_collectAm, 1, _val);
        _minSum = bound(_minSum, 1, _val);
        vm.assume(_collectAm <= _val);
        vm.assume(_minSum <= _val);

        // Setup: initialize contract and set minSum
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // First Put call to set an initial unlockTime
        vm.deal(caller, _val);
        vm.prank(caller);
        c.Put{value: _val}(_lockTime);

        // Record the unlockTime after Put
        (uint unlockTimeBefore,,) = c.Acc(caller);

        // Now call Collect with an amount that will succeed (balance >= minSum and > unlockTime)
        vm.warp(unlockTimeBefore + 1); // ensure block.timestamp > unlockTime
        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _collectAm));

        if (success) {
            (uint unlockTimeAfter,,) = c.Acc(caller);
            // General rule: unlockTime should NOT change because the condition _lockTime+block.timestamp < unlockTime is false
            // (it was set to exactly unlockTimeBefore which is >= block.timestamp+_lockTime)
            assertTrue(unlockTimeAfter == unlockTimeBefore, "unlockTime should not change");
        }
        // If Collect reverted, no state change to check
    }
}

