pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint lockTime, uint depositAmount, uint collectAmount, uint unlockTimeBefore) public {
        vm.assume(caller != address(0));
        vm.assume(lockTime <= type(uint).max - block.timestamp);
        vm.assume(depositAmount > 0 && depositAmount <= caller.balance);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(unlockTimeBefore <= type(uint).max - 1);

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0xcafe));
        c.Initialized();

        // Set initial unlockTime for caller
        vm.store(address(c), keccak256(abi.encode(caller, uint(0))), bytes32(unlockTimeBefore));

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put(lockTime);

        // Get unlockTime before Collect
        (uint utBefore,) = c.Acc(caller);

        // Collect
        vm.prank(caller);
        try c.Collect(collectAmount) {
            (uint utAfter,) = c.Acc(caller);
            assertTrue(utAfter >= utBefore, "unlockTime decreased after Collect");
        } catch {
            // If Collect reverts, the property is trivially satisfied
            assertTrue(true);
        }
